    cl=lambda v:(sel.select_option(v), A.wait_for_timeout(300), A.locator('.rprod').first.locator('.rline select[aria-label="Percent complete"]').first.evaluate("e=>getComputedStyle(e).borderTopColor"))[2]
    ok('dropdown colour: 30 yellow, 80 orange, 100 green', cl('30')=='rgb(227, 181, 5)' and cl('80')=='rgb(240, 138, 36)' and cl('100')=='rgb(46, 157, 107)')
    A.click('button:text-is("Clear all items")'); A.click('#xdlg button:text-is("Remove all items")'); A.wait_for_timeout(500)
    ok('Clear all items empties every product', A.locator('.rline').count()==0 and A.locator('.rprod').count()>=2)
    ok('products have no big summary box and no group headings', A.locator('.rsum').count()==0 and A.locator('.rgrp h3').count()==0)
    A.locator('input[aria-label="Report label"]').fill('Sprint 229 - week 1'); A.locator('input[aria-label="Report label"]').press('Tab'); A.wait_for_timeout(400)
    A.locator('input[aria-label="Week start"]').fill('2026-10-16'); A.wait_for_timeout(400); A.locator('input[aria-label="Week end"]').fill('2026-10-22'); A.wait_for_timeout(500)
    ok('label and dates of the report can be edited', 'Fri 16 Oct 2026' in A.locator('.rhero .rtitle').inner_text() and 'Thu 22 Oct 2026' in A.locator('.rhero .rtitle').inner_text() and A.locator('input[aria-label="Report label"]').input_value()=='Sprint 229 - week 1')
    # progress is calculated from the items below; sections can be added; notes; per-product formatting
    ok('progress starts at 0% with no items', A.locator('.rprog .rmpct').inner_text()=='0%' and all(x=='0%' for x in A.evaluate("[...document.querySelectorAll('.rprog .rmsum .rmpp')].map(e=>e.innerText)")))
    ta=A.locator('.rprod').first.locator('.spadd textarea'); ta.fill('Alpha\nBeta'); A.locator('.rprod').first.locator('button:text-is("Add items")').click(); A.wait_for_timeout(400)
    ss=A.locator('.rprod').first.locator('select[aria-label="Percent complete"]'); ss.nth(0).select_option('40'); A.wait_for_timeout(250); A.locator('.rprod').first.locator('select[aria-label="Percent complete"]').nth(1).select_option('80'); A.wait_for_timeout(300)
    ok('product and overall percentages come from the items (40 and 80 = 60%)', A.locator('.rprog .rmsum').first.locator('.rmpp').inner_text()=='60%' and A.locator('.rprog .rmpct').inner_text()=='60%')
    A.click('#pg-reports button:text-is("+ Product section")'); A.locator('#xdlg input[aria-label="Section name"]').fill('Wasl+'); A.click('#xdlg button:text-is("Add section")'); A.wait_for_timeout(500)
    ok('a new product section appears with its own bar at 0%', 'Wasl+' in A.evaluate("[...document.querySelectorAll('.rprod input.rname')].map(e=>e.value)") and A.locator('.rprog .rmsum:has-text("Wasl+") .rmpp').inner_text()=='0%')
    wp=A.locator('.rprod[data-k^="c"]'); wp.locator('textarea').fill('Gamma'); wp.locator('button:text-is("Add items")').click(); A.wait_for_timeout(300)
    A.locator('.rprod[data-k^="c"]').locator('select[aria-label="Percent complete"]').first.select_option('100'); A.wait_for_timeout(400)
