    A.locator('.rprod').first.locator('.scopebtn').first.click(); A.wait_for_timeout(300)
    ok('an item can be flagged out of scope (grey, whole row)', A.locator('.rprod').first.locator('.scopebtn.on').count()==1 and A.locator('.rprod').first.locator('.rline.oos').count()==1 and A.locator('.rprod').first.locator('.riskbtn.on').count()==0)
    A.locator('.rprod').first.locator('.riskbtn').nth(1).click(); A.wait_for_timeout(300)
    ok('a different item can be flagged at risk (red), independent of scope', A.locator('.rprod').first.locator('.riskbtn.on').count()==1 and A.locator('.rprod').first.locator('.rline.oos').count()==1)
    A.locator('.rprod').first.locator('.scopebtn.on').first.click(); A.wait_for_timeout(300)
    ok('second click removes the out-of-scope flag and the grey row', A.locator('.rprod').first.locator('.scopebtn.on').count()==0 and A.locator('.rprod').first.locator('.rline.oos').count()==0)
    A.locator('.rprod').first.locator('.riskbtn.on').first.click(); A.wait_for_timeout(300)
    ok('second click removes the risk flag', A.locator('.rprod').first.locator('.riskbtn.on').count()==0)
    A.locator('.rprod').first.locator('.scopebtn').first.click(); A.wait_for_timeout(300)
    ni=A.locator('.rprod').first.locator('input.rname'); ni.fill('Plan and Daycare'); ni.press('Tab'); A.wait_for_timeout(400)
