    ok('print builds a clean document with header, summary, items, flag and note', A.evaluate("window.__printed")==1 and A.locator('.rprint .pr-head h1').count()==1 and A.locator('.rprint .pr-big').count()==1 and A.locator('.rprint .pr-item').count()>=2 and A.locator('.rprint .pr-flag').count()==1 and 'Print note' in A.locator('.rprint .pr-note').inner_text() and A.locator('.rprint select, .rprint input, .rprint button').count()==0)
    A.evaluate("document.querySelectorAll('.rprint').forEach(e=>e.remove());document.body.classList.remove('print-pro')")
    A.click('#nav button[data-p="reports"]'); A.wait_for_timeout(300)
