    ok('the composer shows the six tags as colour chips and has focus', pops==['daycare','tifli','plan','ai','finance','initiative'] and A.evaluate("document.activeElement.tagName")=='TEXTAREA' and oct_.locator('.mdchip.on').count()==1)
