    ta=oct_.locator('.mdadd textarea'); ta.fill('Board pack'); ta.press('Enter'); A.wait_for_timeout(500)
    ok('Enter adds the card in the chosen product and the composer stays open on the next card', A.locator('.mdcol[data-mo="2026-10"] .mdcard').count()==1 and A.locator('.mdcol[data-mo="2026-10"] .mdtext').first.inner_text()=='Board pack' and A.locator('.mdcol[data-mo="2026-10"] .mdchip.on').get_attribute('data-k')==pops[1] and A.evaluate("document.activeElement.tagName")=='TEXTAREA' and A.evaluate("document.activeElement.value")=='')
    A.keyboard.type('Second card'); A.keyboard.press('Enter'); A.wait_for_timeout(400)
    ta=A.locator('.mdcol[data-mo="2026-10"] .mdadd textarea'); ta.fill('- Pasted one\n- Pasted two'); ta.press('Enter'); A.wait_for_timeout(500)
    ok('several cards can be added quickly, a pasted list becomes one card per line', A.locator('.mdcol[data-mo="2026-10"] .mdcard').count()==4 and 'Pasted two' in A.locator('.mdcol[data-mo="2026-10"]').inner_text())
    A.keyboard.press('Escape'); A.wait_for_timeout(300)
    ok('Esc closes the composer', A.locator('.mdadd').count()==0 and A.locator('.mdcol[data-mo="2026-10"] .mdopen').count()==1)
    for t in ['Second card','Pasted one','Pasted two']:
        A.locator('.mdcol[data-mo="2026-10"] .mdcard:has-text("%s") .kebab'%t).click(); A.locator('#ctx .mi:text-is("Delete card")').click(); A.click('#xdlg button:text-is("Delete card")'); A.wait_for_timeout(400)
    ok('only the first card is left for the next checks', A.locator('.mdcol[data-mo="2026-10"] .mdcard').count()==1)
