    A.locator('.mdcol[data-mo="2026-10"] .colmore').click(); A.locator('#ctx .mi:text-is("Copy text")').click(); A.wait_for_timeout(400)
    ok('copy text carries the flags and the note', '[BUSINESS PRIORITY]' in A.evaluate("window.__clip") and '[SMALL ENHANCEMENT]' in A.evaluate("window.__clip") and 'Note: Business asked' in A.evaluate("window.__clip"))
    # add months
    A.click('#addmonth'); A.wait_for_timeout(500)
    ok('+ Add month appends the next month', A.locator('.mdcol').count()==3 and A.locator('.mdcol[data-mo="2026-12"]').count()==1 and A.locator('#addmonth').inner_text()=='+ Add month (January 2027)')
    # move a card to another month through its menu
    mc=A.locator('.mdcol[data-mo="2026-10"] .mdcard').first; mid=mc.get_attribute('data-id'); mc.locator('.kebab').click(); A.wait_for_timeout(200)
    A.locator('#ctx .mi:text-is("December 2026")').click(); A.wait_for_timeout(600)
    ok('a card can be moved to another month', A.locator('.mdcol[data-mo="2026-12"] .mdcard[data-id="%s"]'%mid).count()==1 and A.locator('.mdcol[data-mo="2026-10"] .mdcard[data-id="%s"]'%mid).count()==0)
    # no ad hoc item in the card menu any more
    dc=A.locator('.mdcol[data-mo="2026-12"] .mdcard').first; dc.locator('.kebab').click(); A.wait_for_timeout(200)
    ok('the card menu has no ad hoc request item', A.locator('#ctx .mi:has-text("ad hoc")').count()==0 and A.locator('#ctx .mi:text-is("Quick win")').count()==1 and A.locator('#ctx .mi:has-text("Small enhancement")').count()==1)
    A.keyboard.press('Escape'); A.mouse.click(700,60); A.wait_for_timeout(200)
    # edit text
    et=A.locator('.mdcol[data-mo="2026-12"] .mdtext').first; et.click(); A.keyboard.press('Control+a'); A.keyboard.type('Renamed deliverable'); A.locator('#pg-monthly h1').click(); A.wait_for_timeout(500)
    ok('a card title can be edited in place', 'Renamed deliverable' in A.locator('.mdcol[data-mo="2026-12"]').inner_text())
    # filter and search
    A.locator('#pg-monthly input[type=search]').fill('renamed'); A.wait_for_timeout(400)
    ok('search narrows the cards', A.locator('.mdcard').count()==1)
    A.locator('#pg-monthly input[type=search]').fill(''); A.wait_for_timeout(300)
    # copy text
    A.evaluate("()=>{window.__clip='';Object.defineProperty(navigator.clipboard,'writeText',{configurable:true,value:t=>{window.__clip=t;return Promise.resolve();}});}")
    A.locator('.mdcol[data-mo="2026-12"] .colmore').click(); A.locator('#ctx .mi:text-is("Copy text")').click(); A.wait_for_timeout(400)
    ok('copy text lists the month and its cards', 'MONTHLY DELIVERABLES - December 2026' in A.evaluate("window.__clip") and 'Renamed deliverable' in A.evaluate("window.__clip"))
    # delete a card and a month
    dc=A.locator('.mdcol[data-mo="2026-12"] .mdcard').first; dc.locator('.kebab').click(); A.locator('#ctx .mi:text-is("Delete card")').click(); A.click('#xdlg button:text-is("Delete card")'); A.wait_for_timeout(500)
    ok('a card can be deleted', A.locator('.mdcol[data-mo="2026-12"] .mdcard').count()==0)
    A.locator('.mdcol[data-mo="2026-11"] .colmore').click(); A.locator('#ctx .mi:text-is("Delete month")').click(); A.click('#xdlg button:text-is("Delete month")'); A.wait_for_timeout(600)
    ok('a month can be deleted (its column stays, empty)', A.locator('.mdcol[data-mo="2026-11"] .mdcard').count()==0)
    A.set_viewport_size({'width':390,'height':800}); A.wait_for_timeout(400)
    ok('no horizontal page overflow on a phone', not A.evaluate("document.documentElement.scrollWidth>innerWidth+1"))
    A.set_viewport_size({'width':1400,'height':900}); A.wait_for_timeout(300)
    # cards made before the split: the combined Plan / Daycare tag becomes Plan, drafts become visible
    A.evaluate("""()=>{const s=JSON.parse(localStorage.getItem('fk3'));s.reports['mo202612']=Object.assign({},s.reports['mo202612']||{mo:'2026-12',lines:[]},{status:'draft',lines:[{id:'old1',k:'plan_daycare',t:'Legacy card',pct:20,w:1,adhoc:false,src:'',pe:true}]});localStorage.setItem('fk3',JSON.stringify(s));}""")
    A.reload(); A.wait_for_timeout(1800); A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(700)
