    # viewer: read-only board
    C=newpage(ctx,errs); signup(C,'Vic','vic@x.com')
    A.click('#nav button[data-p="admin"]'); A.wait_for_timeout(500)
    A.locator('.card:has-text("Vic") button:text-is("Approve")').first.click(); A.wait_for_timeout(700)
    A.locator('select[aria-label="Access for Vic"]').select_option('viewer'); A.wait_for_timeout(700)
    C.reload(); C.wait_for_timeout(1500); C.click('#nav button[data-p="monthly"]'); C.wait_for_timeout(600)
    ok('executives see the board with every month, read-only', C.locator('.mdcol').count()>=3 and C.locator('.mdcard').count()>=1 and C.locator('#pg-monthly input:not([type=search]), #pg-monthly select:not([aria-label="Filter by tag"]):not([aria-label="Filter by flag"]), #pg-monthly .mdadd, #addmonth, #pg-monthly [contenteditable]').count()==0)
    # live: two editors and an executive working on the board at the same time
    B=newpage(ctx,errs); signup(B,'Ed','ed@x.com'); A.click('#nav button[data-p="admin"]'); A.wait_for_timeout(500)
    A.locator('.card:has-text("Ed") button:text-is("Approve")').first.click(); A.wait_for_timeout(700)
    B.reload(); B.wait_for_timeout(1500); B.click('#nav button[data-p="monthly"]'); B.wait_for_timeout(500); A.click('#nav button[data-p="monthly"]'); A.wait_for_timeout(500)
    ttl=lambda P: P.evaluate("()=>[...document.querySelectorAll('.mdcol[data-mo=\"2026-10\"] .mdtext')].map(e=>e.innerText)")
    ob=B.locator('.mdcol[data-mo="2026-10"]'); ob.locator('.mdopen').click(); B.keyboard.type('half typed by Ed')
    oa=A.locator('.mdcol[data-mo="2026-10"]'); oa.locator('.mdopen').click(); oa.locator('.mdadd textarea').fill('Live from Admin'); oa.locator('.mdadd textarea').press('Enter'); A.wait_for_timeout(1800)
    ok('a card added by one editor appears for the other even while the other is typing, and the draft is kept', 'Live from Admin' in ttl(B) and B.evaluate("document.activeElement.value")=='half typed by Ed')
    B.keyboard.press('Enter'); B.wait_for_timeout(1500)
    ok('both cards are on both screens, nothing was overwritten', 'half typed by Ed' in ttl(A) and 'Live from Admin' in ttl(A) and 'Live from Admin' in ttl(B) and 'half typed by Ed' in ttl(B))
    C.wait_for_timeout(500)
    ok('the executive sees the new cards without reloading', 'Live from Admin' in C.locator('.mdcol[data-mo="2026-10"]').inner_text() and 'half typed by Ed' in C.locator('.mdcol[data-mo="2026-10"]').inner_text())
    lc=A.locator('.mdcol[data-mo="2026-10"] .mdcard:has-text("Live from Admin")'); lc.locator('.mdhp').click(); A.wait_for_timeout(300)
    lc=A.locator('.mdcol[data-mo="2026-10"] .mdcard:has-text("Live from Admin")'); lc.locator('.mdstar').click(); A.wait_for_timeout(300)
    lc=A.locator('.mdcol[data-mo="2026-10"] .mdcard:has-text("Live from Admin")'); lc.locator('.mdnote').click(); A.locator('#xdlg textarea').fill('Seen by executives'); A.click('#xdlg button:text-is("Save")'); A.wait_for_timeout(1800)
    ok('executives see the business priority ribbon, the small-enhancement tag and the note tooltip', C.locator('.mdcard.hp .mdribbon').count()==1 and C.locator('.mdcard .mdsz-enh').count()==1 and C.locator('.mdcard .mdnote.has[data-tip]').count()==1 and C.locator('.mdhp').count()==0)
    ok('no page errors', errs==[])
